theorem extracted_1.{u_5, u_1} {Ω : Type u_1} {G : Type u_5} [mΩ : MeasurableSpace Ω] {μ : Measure Ω}
  [hG : MeasurableSpace G] [inst : AddCommGroup G] [inst_1 : DiscreteMeasurableSpace G] {X Y Z : Ω → G}
  [inst_2 : IsZeroOrProbabilityMeasure μ] (h_indep : IndepFun (⟨X, Y⟩) Z μ) (hX : Measurable X) (hY : Measurable Y)
  (hZ : Measurable Z) (habs : ∀ (x : G), (Measure.map Y μ) {x} = 0 → (Measure.map X μ) {x} = 0)
  (hμ : IsProbabilityMeasure μ) :
  let X' := fun s => (fun x => x + s) ∘ X;
  (X' = fun s => (fun x => x + s) ∘ X) →
    let Y' := fun s => (fun x => x + s) ∘ Y;
    (Y' = fun s => (fun x => x + s) ∘ Y) →
      (∀ (x i : G), (Measure.map (X' i) μ) {x} = (Measure.map X μ) {x - i}) →
        (∀ (x i : G), (Measure.map (Y' i) μ) {x} = (Measure.map Y μ) {x - i}) →
          KL[X + Z ; μ # Y + Z ; μ] ≤ KL[X ; μ # Y ; μ] := by
  fun_prop
